import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { MapPin, Calendar, ArrowRight, X } from "lucide-react";
import { projects } from "../../data/content";
import ImagePlaceholder from "../ui/ImagePlaceholder";
import AnimatedSection from "../ui/AnimatedSection";
import Badge from "../ui/Badge";

export default function Projects() {
  const [selected, setSelected] = useState(null);

  return (
    <section id="projects" className="bg-charcoal-50 section-pad">
      <div className="max-w-7xl mx-auto px-6 lg:px-10">
        {/* Header */}
        <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6 mb-14">
          <div>
            <AnimatedSection variant="fadeUp">
              <span className="eyebrow mb-4 block tracking-widest text-xs uppercase font-semibold">
                Featured Projects
              </span>
            </AnimatedSection>
            <AnimatedSection variant="fadeUp" delay={0.1}>
              <h2 className="font-display text-[clamp(2.2rem,4vw,3.2rem)] leading-[1.12]">
                Delivered at Scale.{" "}
                <em className="text-blue-800 not-italic">Built to Last.</em>
              </h2>
            </AnimatedSection>
          </div>
          <AnimatedSection variant="fadeUp" delay={0.15} className="max-w-sm">
            <p className="text-charcoal-500 text-sm leading-relaxed">
              Click any project to read the full case study — challenge, solution, and measurable impact.
            </p>
          </AnimatedSection>
        </div>

        {/* Projects grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
          {projects.map((proj, i) => (
            <AnimatedSection key={proj.id} variant="fadeUp" delay={i * 0.1}>
              <ProjectCard proj={proj} onOpen={() => setSelected(proj)} />
            </AnimatedSection>
          ))}
        </div>
      </div>

      {/* Modal */}
      <AnimatePresence>
        {selected && (
          <ProjectModal proj={selected} onClose={() => setSelected(null)} />
        )}
      </AnimatePresence>
    </section>
  );
}

function ProjectCard({ proj, onOpen }) {
  const [hovered, setHovered] = useState(false);

  return (
    <motion.div
      className="relative bg-white border border-charcoal-200 rounded-2xl overflow-hidden cursor-pointer group flex flex-col"
      whileHover={{ y: -5, boxShadow: "0 24px 60px rgba(11,61,143,0.12)" }}
      transition={{ duration: 0.3 }}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onClick={onOpen}
    >
      {/* ─── Image area — full-size, contain, no crop ─── */}
      <div
        className="relative w-full bg-charcoal-100 flex items-center justify-center overflow-hidden"
        style={{ minHeight: 260 }}
      >
        {proj.image ? (
          <>
            <img
              src={proj.image}
              alt={proj.name}
              className="w-full h-full"
              style={{
                display: "block",
                objectFit: "contain",
                objectPosition: "center",
                maxHeight: 320,
                width: "100%",
                imageRendering: "high-quality",
              }}
              loading="lazy"
              decoding="async"
            />
            {/* Gradient footer */}
            <div
              className="absolute bottom-0 left-0 right-0 h-16 pointer-events-none"
              style={{
                background:
                  "linear-gradient(to top, rgba(248,249,250,0.9) 0%, transparent 100%)",
              }}
            />
          </>
        ) : (
          <ImagePlaceholder
            image={proj.image}
            imagePlaceholderClass={proj.imagePlaceholderClass}
            imagePlaceholderText={proj.name}
            alt={proj.name}
            className="w-full h-full"
            style={{ objectFit: "contain", maxHeight: 320 }}
          />
        )}

        {/* Hover overlay */}
        <motion.div
          className="absolute inset-0 bg-charcoal-950/25 pointer-events-none"
          animate={{ opacity: hovered ? 1 : 0 }}
          transition={{ duration: 0.3 }}
        />

        {/* Tags */}
        <div className="absolute top-4 left-4 z-10 flex gap-2">
          {proj.tags.map((tag) => (
            <Badge key={tag} variant="dark">{tag}</Badge>
          ))}
        </div>

        {/* Year */}
        <div className="absolute top-4 right-4 z-10">
          <Badge variant="dark">{proj.year}</Badge>
        </div>
      </div>

      {/* ─── Body ─── */}
      <div className="p-6 flex flex-col flex-1">
        <div className="flex items-center gap-1.5 text-charcoal-400 text-[11.5px] font-semibold mb-3">
          <MapPin size={11} />
          {proj.location}
        </div>
        <h3 className="font-display text-[1.2rem] text-charcoal-900 leading-snug mb-3 group-hover:text-blue-800 transition-colors duration-200">
          {proj.name}
        </h3>
        <p className="text-charcoal-500 text-[13px] leading-[1.7] line-clamp-2">
          {proj.challenge}
        </p>

        {/* Impact strip */}
        <div className="mt-auto pt-5 border-t border-charcoal-100 flex items-center justify-between">
          <div>
            <p className="text-[10px] font-bold tracking-[0.15em] uppercase text-blue-800 mb-1">
              Impact
            </p>
            <p className="text-[12.5px] text-charcoal-600 font-medium leading-snug">
              {proj.impact}
            </p>
          </div>
          <motion.div
            className="w-10 h-10 rounded-full bg-blue-800 flex items-center justify-center flex-shrink-0 shadow-md shadow-blue-800/20"
            animate={{ scale: hovered ? 1 : 0.85, opacity: hovered ? 1 : 0.5 }}
            transition={{ duration: 0.25 }}
          >
            <ArrowRight size={15} className="text-white" />
          </motion.div>
        </div>
      </div>
    </motion.div>
  );
}

